package com.bank.dto.mapper;

import com.bank.dto.dto.EmployeeDTO;
import com.bank.dto.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class DirectoryMapper {
    private static final Logger log = Logger.getLogger(DirectoryMapper.class.getName());

    public List<EmployeeDTO> toDtos(List<Employee> employees) {
        log.info(() -> "Mapping " + employees.size() + " employees to safe DTOs");
        return employees.stream()
                // Build a slim DTO per employee — salary deliberately excluded.
                .map(e -> new EmployeeDTO(e.getName(), e.getDepartment()))
                .collect(Collectors.toList());
    }
}
