package com.bank.dto;

import com.bank.dto.dto.EmployeeDTO;
import com.bank.dto.mapper.DirectoryMapper;
import com.bank.dto.model.Employee;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT",    new BigDecimal("95000")),
            new Employee("Priya",  "Sales", new BigDecimal("72000"))
        );

        List<EmployeeDTO> dtos = new DirectoryMapper().toDtos(staff);
        dtos.forEach(d -> log.info(() -> "Public directory entry: " + d));
    }
}
